        public void completed(final byte[] result) {
            count.incrementAndGet();
        }

        @Override
        public void failed(final Exception ex) {
            count.incrementAndGet();
        }

        @Override
        public void cancelled() {
            count.incrementAndGet();
        }
    });
    consumer.consume(ByteBuffer.wrap(new byte[] { '1', '2', '3' }));
