                            String l;
                            int count = 0;
                            while ((l = reader.readLine()) != null) {
                                writer.write(l);
                                writer.write("\r\n");
                                count++;
                                if (count % 500 == 0) {
                                    Thread.sleep(500);
                                }
                            }
                            writer.flush();
