public void testPipelinedRequests() throws Exception {
    server.start();
    final Future<ListenerEndpoint> future = server.listen(new InetSocketAddress(0));
    final ListenerEndpoint listener = future.get();
    final InetSocketAddress address = (InetSocketAddress) listener.getAddress();
    requester.start();
    final HttpHost target = new HttpHost(scheme.id, "localhost", address.getPort());
    final Future<AsyncClientEndpoint> endpointFuture = requester.connect(target, Timeout.ofSeconds(5));
    final AsyncClientEndpoint endpoint = endpointFuture.get(TIMEOUT.getDuration(), TIMEOUT.getTimeUnit());
    try {
        final Queue<Future<Message<HttpResponse, String>>> queue = new LinkedList<>();
        queue.add(endpoint.execute(new BasicRequestProducer("POST", target, "/stuff", new StringAsyncEntityProducer("some stuff", ContentType.TEXT_PLAIN)), new BasicResponseConsumer<>(new StringAsyncEntityConsumer()), null));
        queue.add(endpoint.execute(new BasicRequestProducer("POST", target, "/other-stuff", new StringAsyncEntityProducer("some other stuff", ContentType.TEXT_PLAIN)), new BasicResponseConsumer<>(new StringAsyncEntityConsumer()), null));
        queue.add(endpoint.execute(new BasicRequestProducer("POST", target, "/more-stuff", new StringAsyncEntityProducer("some more stuff", ContentType.TEXT_PLAIN)), new BasicResponseConsumer<>(new StringAsyncEntityConsumer()), null));
        while (!queue.isEmpty()) {
            final Future<Message<HttpResponse, String>> resultFuture = queue.remove();
            final Message<HttpResponse, String> message = resultFuture.get(TIMEOUT.getDuration(), TIMEOUT.getTimeUnit());
            Assert.assertThat(message, CoreMatchers.notNullValue());
            final HttpResponse response = message.getHead();
            Assert.assertThat(response.getCode(), CoreMatchers.equalTo(HttpStatus.SC_OK));
            final String body = message.getBody();
            Assert.assertThat(body, CoreMatchers.containsString("stuff"));
        }
    } finally {
        endpoint.releaseAndReuse();
    }
}

@Test
public void testEndpointUpAndDown() throws Exception {
    ioReactor.start();
    Set<ListenerEndpoint> endpoints = ioReactor.getEndpoints();
    Assert.assertNotNull(endpoints);
    Assert.assertEquals(0, endpoints.size());
    final Future<ListenerEndpoint> future1 = ioReactor.listen(new InetSocketAddress(0));
    final ListenerEndpoint endpoint1 = future1.get();
    final Future<ListenerEndpoint> future2 = ioReactor.listen(new InetSocketAddress(0));
    final ListenerEndpoint endpoint2 = future2.get();
    final int port = ((InetSocketAddress) endpoint2.getAddress()).getPort();
    endpoints = ioReactor.getEndpoints();
    Assert.assertNotNull(endpoints);
    Assert.assertEquals(2, endpoints.size());
    endpoint1.close();
    endpoints = ioReactor.getEndpoints();
    Assert.assertNotNull(endpoints);
    Assert.assertEquals(1, endpoints.size());
    final ListenerEndpoint endpoint = endpoints.iterator().next();
    Assert.assertEquals(port, ((InetSocketAddress) endpoint.getAddress()).getPort());
    ioReactor.close(CloseMode.GRACEFUL);
    ioReactor.awaitShutdown(TimeValue.ofSeconds(5));
    Assert.assertEquals(IOReactorStatus.SHUT_DOWN, ioReactor.getStatus());
}

@Test
public void testEndpointAlreadyBound() throws Exception {
    ioReactor.start();
    final Future<ListenerEndpoint> future1 = ioReactor.listen(new InetSocketAddress(0));
    final ListenerEndpoint endpoint1 = future1.get();
    final int port = ((InetSocketAddress) endpoint1.getAddress()).getPort();
    final Future<ListenerEndpoint> future2 = ioReactor.listen(new InetSocketAddress(port));
    try {
        future2.get();
        Assert.fail("ExecutionException expected");
    } catch (final ExecutionException expected) {
    }
    ioReactor.close(CloseMode.GRACEFUL);
    ioReactor.awaitShutdown(TimeValue.ofSeconds(5));
    Assert.assertEquals(IOReactorStatus.SHUT_DOWN, ioReactor.getStatus());
}

@Test
public void testSimpleRequest() throws Exception {
    final InetSocketAddress address = startClientAndServer();
    final byte[] input = new byte[1024];
    RANDOM.nextBytes(input);
    final Publisher<ByteBuffer> publisher = Flowable.just(ByteBuffer.wrap(input));
    final ReactiveEntityProducer producer = new ReactiveEntityProducer(publisher, input.length, null, null);
    final BasicRequestProducer request = getRequestProducer(address, producer);
    final ReactiveResponseConsumer consumer = new ReactiveResponseConsumer();
    requester.execute(request, consumer, SOCKET_TIMEOUT, null);
    final Message<HttpResponse, Publisher<ByteBuffer>> response = consumer.getResponseFuture().get(RESULT_TIMEOUT.getDuration(), RESULT_TIMEOUT.getTimeUnit());
    final ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
    final WritableByteChannel writableByteChannel = Channels.newChannel(byteArrayOutputStream);
    for (final ByteBuffer byteBuffer : Observable.fromPublisher(response.getBody()).toList().blockingGet()) {
        writableByteChannel.write(byteBuffer);
    }
    writableByteChannel.close();
    final byte[] output = byteArrayOutputStream.toByteArray();
    Assert.assertArrayEquals(input, output);
}

@Test
public void testLongRunningRequest() throws Exception {
    final InetSocketAddress address = startClientAndServer();
    final AtomicLong requestLength = new AtomicLong(0L);
    final AtomicReference<MessageDigest> requestDigest = new AtomicReference<>(newDigest());
    final Publisher<ByteBuffer> publisher = Flowable.rangeLong(1, 100).map(new Function<Long, ByteBuffer>() {

        @Override
        public ByteBuffer apply(final Long seed) {
            final Random random = new Random(seed);
            // Using blocks slightly larger than the HTTP/2 window size serves to exercise the input window
            // management code
            final byte[] bytes = new byte[65535 + 7];
            requestLength.addAndGet(bytes.length);
            random.nextBytes(bytes);
            return ByteBuffer.wrap(bytes);
        }
    }).doOnNext(new Consumer<ByteBuffer>() {

        @Override
        public void accept(final ByteBuffer byteBuffer) {
            requestDigest.get().update(byteBuffer.duplicate());
        }
    });
    final ReactiveEntityProducer producer = new ReactiveEntityProducer(publisher, -1, null, null);
    final BasicRequestProducer request = getRequestProducer(address, producer);
    final ReactiveResponseConsumer consumer = new ReactiveResponseConsumer();
    requester.execute(request, consumer, SOCKET_TIMEOUT, null);
    final Message<HttpResponse, Publisher<ByteBuffer>> response = consumer.getResponseFuture().get(RESULT_TIMEOUT.getDuration(), RESULT_TIMEOUT.getTimeUnit());
    final AtomicLong responseLength = new AtomicLong(0);
    final AtomicReference<MessageDigest> responseDigest = new AtomicReference<>(newDigest());
    Flowable.fromPublisher(response.getBody()).blockingForEach(new Consumer<ByteBuffer>() {

        @Override
        public void accept(final ByteBuffer byteBuffer) {
            responseLength.addAndGet(byteBuffer.remaining());
            responseDigest.get().update(byteBuffer);
        }
    });
    Assert.assertEquals(requestLength.get(), responseLength.get());
    Assert.assertArrayEquals(requestDigest.get().digest(), responseDigest.get().digest());
}

@Test
public void testManySmallBuffers() throws Exception {
    // This test is not flaky. If it starts randomly failing, then there is a problem with how
    // ReactiveDataConsumer signals capacity with its capacity channel. The situations in which
    // this kind of bug manifests depend on the ordering of several events on different threads
    // so it's unlikely to consistently occur.
    final InetSocketAddress address = startClientAndServer();
    for (int i = 0; i < 10; i++) {
        final AtomicLong requestLength = new AtomicLong(0L);
        final AtomicReference<MessageDigest> requestDigest = new AtomicReference<>(newDigest());
        final Publisher<ByteBuffer> publisher = Flowable.rangeLong(1, 1_000).map(new Function<Long, ByteBuffer>() {

            @Override
            public ByteBuffer apply(final Long seed) {
                final Random random = new Random(seed);
                final byte[] bytes = new byte[1024];
                requestLength.addAndGet(bytes.length);
                random.nextBytes(bytes);
                return ByteBuffer.wrap(bytes);
            }
        }).doOnNext(new Consumer<ByteBuffer>() {

            @Override
            public void accept(final ByteBuffer byteBuffer) {
                requestDigest.get().update(byteBuffer.duplicate());
            }
        });
        final ReactiveEntityProducer producer = new ReactiveEntityProducer(publisher, -1, null, null);
        final BasicRequestProducer request = getRequestProducer(address, producer);
        final ReactiveResponseConsumer consumer = new ReactiveResponseConsumer();
        requester.execute(request, consumer, SOCKET_TIMEOUT, null);
        final Message<HttpResponse, Publisher<ByteBuffer>> response = consumer.getResponseFuture().get(RESULT_TIMEOUT.getDuration(), RESULT_TIMEOUT.getTimeUnit());
        final AtomicLong responseLength = new AtomicLong(0);
        final AtomicReference<MessageDigest> responseDigest = new AtomicReference<>(newDigest());
        Flowable.fromPublisher(response.getBody()).doOnNext(new Consumer<ByteBuffer>() {

            @Override
            public void accept(final ByteBuffer byteBuffer) {
                responseLength.addAndGet(byteBuffer.remaining());
                responseDigest.get().update(byteBuffer);
            }
        }).// This requests Long.MAX_VALUE objects and guarantees we won't call request again
        blockingLast();
        Assert.assertEquals(requestLength.get(), responseLength.get());
        Assert.assertArrayEquals(requestDigest.get().digest(), responseDigest.get().digest());
    }
}

@Test
public void testRequestError() throws Exception {
    final InetSocketAddress address = startClientAndServer();
    final RuntimeException exceptionThrown = new RuntimeException("Test");
    final Publisher<ByteBuffer> publisher = Flowable.error(exceptionThrown);
    final ReactiveEntityProducer producer = new ReactiveEntityProducer(publisher, 100, null, null);
    final BasicRequestProducer request = getRequestProducer(address, producer);
    final ReactiveResponseConsumer consumer = new ReactiveResponseConsumer();
    final Future<Void> future = requester.execute(request, consumer, SOCKET_TIMEOUT, null);
    try {
        future.get(RESULT_TIMEOUT.getDuration(), RESULT_TIMEOUT.getTimeUnit());
        Assert.fail("Expected exception");
    } catch (final ExecutionException ex) {
        Assert.assertTrue(ex.getCause() instanceof HttpStreamResetException);
        Assert.assertSame(exceptionThrown, ex.getCause().getCause());
    }
}

@Test
public void testRequestTimeout() throws Exception {
    final InetSocketAddress address = startClientAndServer();
    final AtomicBoolean requestPublisherWasCancelled = new AtomicBoolean(false);
    final Publisher<ByteBuffer> publisher = Flowable.<ByteBuffer>never().doOnCancel(new Action() {

        @Override
        public void run() {
            requestPublisherWasCancelled.set(true);
        }
    });
    final ReactiveEntityProducer producer = new ReactiveEntityProducer(publisher, -1, null, null);
    final BasicRequestProducer request = getRequestProducer(address, producer);
    final ReactiveResponseConsumer consumer = new ReactiveResponseConsumer();
    final Future<Void> future = requester.execute(request, consumer, Timeout.ofSeconds(1), null);
    try {
        future.get(RESULT_TIMEOUT.getDuration(), RESULT_TIMEOUT.getTimeUnit());
    } catch (final ExecutionException ex) {
        Assert.assertTrue(requestPublisherWasCancelled.get());
        final Throwable cause = ex.getCause();
        if (versionPolicy == HttpVersionPolicy.FORCE_HTTP_1) {
            Assert.assertTrue("Expected SocketTimeoutException, but got " + cause.getClass().getName(), cause instanceof SocketTimeoutException);
        } else if (versionPolicy == HttpVersionPolicy.FORCE_HTTP_2) {
            Assert.assertTrue(format("Expected RST_STREAM, but %s was thrown", cause.getClass().getName()), cause instanceof HttpStreamResetException);
        } else {
            Assert.fail("Unknown HttpVersionPolicy: " + versionPolicy);
        }
    }
}

@Test
public void testResponseCancellation() throws Exception {
    final InetSocketAddress address = startClientAndServer();
    final AtomicBoolean requestPublisherWasCancelled = new AtomicBoolean(false);
    final AtomicReference<Throwable> requestStreamError = new AtomicReference<>();
    final Publisher<ByteBuffer> publisher = Flowable.rangeLong(Long.MIN_VALUE, Long.MAX_VALUE).map(new Function<Long, ByteBuffer>() {

        @Override
        public ByteBuffer apply(final Long seed) throws Exception {
            final Random random = new Random(seed);
            final byte[] bytes = new byte[1 + random.nextInt(1024)];
            random.nextBytes(bytes);
            return ByteBuffer.wrap(bytes);
        }
    }).doOnCancel(new Action() {

        @Override
        public void run() throws Exception {
            requestPublisherWasCancelled.set(true);
        }
    }).doOnError(new Consumer<Throwable>() {

        @Override
        public void accept(final Throwable throwable) throws Exception {
            requestStreamError.set(throwable);
        }
    });
    final ReactiveEntityProducer producer = new ReactiveEntityProducer(publisher, -1, null, null);
    final BasicRequestProducer request = getRequestProducer(address, producer);
    final ReactiveResponseConsumer consumer = new ReactiveResponseConsumer();
    final Future<Void> future = requester.execute(request, consumer, SOCKET_TIMEOUT, null);
    final Message<HttpResponse, Publisher<ByteBuffer>> response = consumer.getResponseFuture().get(RESULT_TIMEOUT.getDuration(), RESULT_TIMEOUT.getTimeUnit());
    final AtomicBoolean responsePublisherWasCancelled = new AtomicBoolean(false);
    final List<ByteBuffer> outputBuffers = Flowable.fromPublisher(response.getBody()).doOnCancel(new Action() {

        @Override
        public void run() throws Exception {
            responsePublisherWasCancelled.set(true);
        }
    }).take(3).toList().blockingGet();
    Assert.assertEquals(3, outputBuffers.size());
    Assert.assertTrue("The response subscription should have been cancelled", responsePublisherWasCancelled.get());
    try {
        future.get(RESULT_TIMEOUT.getDuration(), RESULT_TIMEOUT.getTimeUnit());
        Assert.fail("Expected exception");
    } catch (final ExecutionException | CancellationException ex) {
        Assert.assertTrue(ex.getCause() instanceof HttpStreamResetException);
        Assert.assertTrue(requestPublisherWasCancelled.get());
        Assert.assertNull(requestStreamError.get());
    }
}
